import 'package:flutter_test/flutter_test.dart';
import 'package:terrakin/chain/abi.dart';

// Expected calldata from `cast calldata`; guards the hand-rolled encoding of
// the Loop Capture, Convergence and Dead Drop calls.
void main() {
  const me = '0xf1ff4a574790f52dd243247e9f02d251322a0885';

  test('claimLoop', () {
    String arr(List<BigInt> l) => Abi.uint(l.length) + l.map(Abi.word).join();
    final got = Abi.call('0xaf4299f2', [Abi.uint(1793255224), Abi.uint(1793255400), null, null, null],
        [arr([BigInt.parse('9248282412599758176'), BigInt.two]), arr([BigInt.from(3)]), Abi.hexBytes('0xabcdef')]);
    expect(got, '');
  });

  test('join', () {
    final head = Abi.address(me) +
        Abi.bytes32('0x0bf8ad39cb56dd92ffde586060bf5cbbe64215aefdd49aae793f7c254068c49b') +
        Abi.uint(3) +
        Abi.word(BigInt.from(23170273)) +
        Abi.word(BigInt.from(-88565470)) +
        Abi.uint(1793336400) +
        Abi.uint(1793336520);
    expect(Abi.call('0x7794202d', [head, null], [Abi.hexBytes('0x1122')]), '');
  });

  test('drop', () {
    final spot = Abi.address(me) +
        Abi.word(BigInt.parse('9248282412599758176')) +
        Abi.bytes32('0x0bf8ad39cb56dd92ffde586060bf5cbbe64215aefdd49aae793f7c254068c49b') +
        Abi.uint(1793336520);
    final got = Abi.call(
      '0x2a155d45',
      [spot, null, null, null, Abi.uint(0), Abi.address('0x0000000000000000000000000000000000000000'), Abi.uint(1793600000)],
      [Abi.hexBytes('0x1122'), Abi.hexBytes('0x010203'), Abi.string('Under the bench')],
    );
    expect(got, '');
  });
}
